import { config } from '../config';
import { isKnownIranProvider } from './providers';

export type VpnStatus = 'checking' | 'on' | 'off' | 'error';

async function fetchVpnApi(): Promise<boolean> {
  const res = await fetch(config.vpnApiUrl, {
    cache: 'no-store',
    headers: { Accept: 'application/json' },
  });

  if (!res.ok) {
    throw new Error(`VPN API responded with ${res.status}`);
  }

  const data: unknown = await res.json();
  if (typeof data !== 'boolean') {
    throw new Error('Unexpected VPN API payload');
  }

  return data;
}

/** Best-effort client ASN from Netil speed meta (same egress as /vpn). */
async function fetchClientAsn(): Promise<string | number | null> {
  const netil = config.speed.endpoints.find((e) => e.id === 'netil');
  if (!netil) return null;

  try {
    const res = await fetch(netil.metaUrl, {
      cache: 'no-store',
      mode: 'cors',
      headers: { Accept: 'application/json' },
    });
    if (!res.ok) return null;
    const data = (await res.json()) as { asn?: unknown };
    if (typeof data.asn === 'number' || typeof data.asn === 'string') {
      return data.asn;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * VPN is active when the API reports it, or when the client ASN is not
 * listed in data/providers.json (double-check against known Iranian ISPs).
 */
export async function checkVpn(): Promise<boolean> {
  const [apiVpn, asn] = await Promise.all([fetchVpnApi(), fetchClientAsn()]);

  if (apiVpn) return true;

  // Double-check: known ASN required for "VPN off".
  if (asn !== null && !isKnownIranProvider(asn)) {
    return true;
  }

  return false;
}
