import providersData from '../../data/providers.json';

export type NetworkProvider = {
  name_fa: string;
  name_en: string;
  asns: string[];
};

type ProvidersFile = {
  iran_network_providers: {
    mobile_operators: NetworkProvider[];
    fixed_broadband_fcp: NetworkProvider[];
    enterprise_regional: NetworkProvider[];
    infrastructure: NetworkProvider[];
  };
};

const data = providersData as ProvidersFile;

function allProviders(): NetworkProvider[] {
  const groups = data.iran_network_providers;
  return [
    ...groups.mobile_operators,
    ...groups.fixed_broadband_fcp,
    ...groups.enterprise_regional,
    ...groups.infrastructure,
  ];
}

/** Normalize ASN to `ASxxxxx` uppercase form. */
export function normalizeAsn(asn: string | number | null | undefined): string | null {
  if (asn === null || asn === undefined) return null;
  const raw = String(asn).trim().toUpperCase();
  if (!raw) return null;
  const withPrefix = raw.startsWith('AS') ? raw : `AS${raw}`;
  return /^AS\d+$/.test(withPrefix) ? withPrefix : null;
}

const asnToProvider = new Map<string, NetworkProvider>();
for (const provider of allProviders()) {
  for (const asn of provider.asns) {
    const key = normalizeAsn(asn);
    if (key) asnToProvider.set(key, provider);
  }
}

export function findProviderByAsn(
  asn: string | number | null | undefined,
): NetworkProvider | null {
  const key = normalizeAsn(asn);
  if (!key) return null;
  return asnToProvider.get(key) ?? null;
}

/** Persian display name for UI, or null if ASN is not a known Iranian provider. */
export function providerNameFa(
  asn: string | number | null | undefined,
): string | null {
  return findProviderByAsn(asn)?.name_fa ?? null;
}

/** True when the ASN is listed in data/providers.json. */
export function isKnownIranProvider(
  asn: string | number | null | undefined,
): boolean {
  return findProviderByAsn(asn) !== null;
}
